-- Run this in the Supabase SQL Editor (Table Editor doesn't do bulk work
-- like this). Safe to re-run — the column add, policy, and insert are all
-- idempotent. (A live check against the actual database while building
-- this found the `slug` column and all 36 rows already present — looks
-- like this, or something equivalent, was already run by hand at some
-- point. This file is still worth keeping/running so the schema is
-- captured in the repo, and it'll no-op cleanly against existing data.)
--
-- What this does:
--   1. Adds a `slug` column to `businesses`, matching the filename/id each
--      listing already uses under src/content/listings/*.json — this is
--      the join key /l/[slug].astro uses at build time to find the
--      matching businesses row (for the "Claim This Listing" feature).
--   2. Adds a public read policy so an anonymous build-time query (and any
--      visitor, e.g. to check "is this claimed yet?") can see approved
--      businesses. There was no SELECT policy on this table before now —
--      only owners could read their own row.
--   3. Backfills one businesses row per existing listing (owner_id left
--      NULL — unclaimed — approved = true, since these are the site's
--      real, already-published listings). Without this, none of the 36
--      real listings on the site would have anything for "Claim This
--      Listing" to attach to.

alter table public.businesses
  add column if not exists slug text unique;

-- drop-then-create rather than a bare CREATE POLICY: Postgres has no
-- CREATE POLICY IF NOT EXISTS, and this needs to be safe to re-run.
drop policy if exists "Public can view approved businesses" on public.businesses;

create policy "Public can view approved businesses"
  on public.businesses
  for select
  to anon, authenticated
  using (approved = true);

on conflict (slug) do nothing;
